def fizzbuzz(n: int) -> list[str]:
    if n < 0:
        raise ValueError("n must be a non-negative integer.")

    if n == 0:
        return []

    result = []
    for i in range(1, n + 1):
        is_fizz = (i % 3 == 0)
        is_buzz = (i % 5 == 0)

        if is_fizz and is_buzz:
            result.append("FizzBuzz")
        elif is_fizz:
            result.append("Fizz")
        elif is_buzz:
            result.append("Buzz")
        else:
            result.append(str(i))

